window.XV_TIMING = {"total":64997,"scenes":[{"start":0,"dur":12644},{"start":12644,"dur":6349},{"start":18993,"dur":10588},{"start":29581,"dur":18425},{"start":48006,"dur":10382},{"start":58388,"dur":6609}],"cues":{"v1a":450,"v1b":3763,"v1c":5885,"v1d":8785,"v2a":13094,"v2b":15998,"v3a":19243,"v3b":20424,"v3c":23364,"v3d":26495,"v4a":30031,"v4b":32185,"v4c":36098,"v4d":39366,"v4e":41034,"v4f":42843,"v4g":44829,"v5a":48456,"v5b":52569,"v5c":53539,"v5d":54509,"v5e":55479,"v5f":56529,"v6a":58838,"v6b":62338},"captions":{"en":[{"id":"v1a","scene":0,"start":450,"end":3703,"text":"Ten years ago, sustainability reporting was a nice extra."},{"id":"v1b","scene":0,"start":3763,"end":5825,"text":"Today, it’s *expected*."},{"id":"v1c","scene":0,"start":5885,"end":8725,"text":"In 2025, *22,000+ companies* reported to CDP."},{"id":"v1d","scene":0,"start":8785,"end":12494,"text":"Together, they’re worth *more than half* the world’s stock market."},{"id":"v2a","scene":1,"start":13094,"end":15938,"text":"Yes, it’s about the planet and its people."},{"id":"v2b","scene":1,"start":15998,"end":18843,"text":"But the real reason is *closer to home*."},{"id":"v3a","scene":2,"start":19243,"end":20364,"text":"*Your customers.*"},{"id":"v3b","scene":2,"start":20424,"end":23304,"text":"Whether you sell to businesses or to consumers,"},{"id":"v3c","scene":2,"start":23364,"end":26435,"text":"they compare you with a *greener competitor*."},{"id":"v3d","scene":2,"start":26495,"end":29431,"text":"EcoVadis already rates *175,000+ companies*."},{"id":"v4a","scene":3,"start":30031,"end":32125,"text":"Then Europe made it *law*."},{"id":"v4b","scene":3,"start":32185,"end":36038,"text":"Under the *CSRD*, the largest companies must now report in detail."},{"id":"v4c","scene":3,"start":36098,"end":39306,"text":"To do that, they need data from their suppliers."},{"id":"v4d","scene":3,"start":39366,"end":40974,"text":"That means *you*."},{"id":"v4e","scene":3,"start":41034,"end":42783,"text":"Being transparent isn’t enough."},{"id":"v4f","scene":3,"start":42843,"end":44769,"text":"You have to show you’re *improving*,"},{"id":"v4g","scene":3,"start":44829,"end":47856,"text":"on environment, social and governance."},{"id":"v5a","scene":4,"start":48456,"end":52509,"text":"The good news? Start early and it’s *easier than it looks*."},{"id":"v5b","scene":4,"start":52569,"end":53479,"text":"Measure."},{"id":"v5c","scene":4,"start":53539,"end":54449,"text":"Decide."},{"id":"v5d","scene":4,"start":54509,"end":55419,"text":"Disclose."},{"id":"v5e","scene":4,"start":55479,"end":56469,"text":"Act."},{"id":"v5f","scene":4,"start":56529,"end":58238,"text":"*One step at a time.*"},{"id":"v6a","scene":5,"start":58838,"end":62278,"text":"Ready to start? The free resources are just below."},{"id":"v6b","scene":5,"start":62338,"end":64847,"text":"Or *write to me* today."}],"fr":[{"id":"v1a","scene":0,"start":450,"end":3703,"text":"Il y a dix ans, le reporting de durabilité était un petit plus."},{"id":"v1b","scene":0,"start":3763,"end":5825,"text":"Aujourd’hui, il est *attendu*."},{"id":"v1c","scene":0,"start":5885,"end":8725,"text":"En 2025, *plus de 22 000 entreprises* ont répondu au CDP."},{"id":"v1d","scene":0,"start":8785,"end":12494,"text":"Ensemble, elles pèsent *plus de la moitié* de la bourse mondiale."},{"id":"v2a","scene":1,"start":13094,"end":15938,"text":"Bien sûr, il s’agit de la planète et de ses habitants."},{"id":"v2b","scene":1,"start":15998,"end":18843,"text":"Mais la vraie raison est *plus proche de vous*."},{"id":"v3a","scene":2,"start":19243,"end":20364,"text":"*Vos clients.*"},{"id":"v3b","scene":2,"start":20424,"end":23304,"text":"Que vous vendiez à des entreprises ou à des particuliers,"},{"id":"v3c","scene":2,"start":23364,"end":26435,"text":"ils vous comparent à un *concurrent plus durable*."},{"id":"v3d","scene":2,"start":26495,"end":29431,"text":"EcoVadis note déjà *plus de 175 000 entreprises*."},{"id":"v4a","scene":3,"start":30031,"end":32125,"text":"Puis l’Europe en a fait une *loi*."},{"id":"v4b","scene":3,"start":32185,"end":36038,"text":"Avec la *CSRD*, les plus grandes entreprises doivent tout publier en détail."},{"id":"v4c","scene":3,"start":36098,"end":39306,"text":"Pour cela, elles ont besoin des données de leurs fournisseurs."},{"id":"v4d","scene":3,"start":39366,"end":40974,"text":"C’est-à-dire *vous*."},{"id":"v4e","scene":3,"start":41034,"end":42783,"text":"La transparence ne suffit pas."},{"id":"v4f","scene":3,"start":42843,"end":44769,"text":"Il faut montrer que vous *progressez*,"},{"id":"v4g","scene":3,"start":44829,"end":47856,"text":"sur l’environnement, le social et la gouvernance."},{"id":"v5a","scene":4,"start":48456,"end":52509,"text":"La bonne nouvelle ? En commençant tôt, c’est *plus simple qu’il n’y paraît*."},{"id":"v5b","scene":4,"start":52569,"end":53479,"text":"Mesurer."},{"id":"v5c","scene":4,"start":53539,"end":54449,"text":"Décider."},{"id":"v5d","scene":4,"start":54509,"end":55419,"text":"Publier."},{"id":"v5e","scene":4,"start":55479,"end":56469,"text":"Agir."},{"id":"v5f","scene":4,"start":56529,"end":58238,"text":"*Une étape à la fois.*"},{"id":"v6a","scene":5,"start":58838,"end":62278,"text":"Prêt à commencer ? Les ressources gratuites sont juste en dessous."},{"id":"v6b","scene":5,"start":62338,"end":64847,"text":"Ou *écrivez-moi* dès aujourd’hui."}]}};
